export interface Cue {
  start: number // seconds
  end: number // seconds
  text: string
}

export interface CaptionTrack {
  baseUrl: string
  languageCode: string
  /** `asr` = auto-generated by YouTube. Used only when no human-made track exists. */
  kind?: string
  name?: string
}

export type Stage = 'LEARNING' | 'KNOWN' | 'SKIPPED'

interface SavedBase {
  id: string
  langCode: string
  translationLang: string
  stage: Stage
  createdAt: number
  updatedAt: number
}

export interface SavedWord extends SavedBase {
  itemType: 'WORD'
  text: string
  translations: string[]
  /** Sentence where the word was marked. */
  context: { sentence: string; translation: string | null } | null
  source: VideoRef | null
  /** Example sentences from the AI, for the review card. */
  examples?: Example[]
  /** FSRS review state. Missing = new card, never reviewed. */
  review?: ReviewCard
  /** For example `EXPRESSION_TAG`. */
  tags?: string[]
  /** See `WordInfo`. */
  headword?: string
  plural?: string
  ipa?: string
}

/** Tag of a saved multi-word expression (phrasal verb, idiom, ...), saved from the word popup. */
export const EXPRESSION_TAG = 'expression'

/** The word in `sentence` is marked with `*`, also when its form is different. */
export interface Example {
  sentence: string
  translation: string
}

/** The ts-fsrs `Card`, with dates as ms so chrome.storage can keep it. */
export interface ReviewCard {
  due: number
  stability: number
  difficulty: number
  elapsed_days: number
  scheduled_days: number
  learning_steps: number
  reps: number
  lapses: number
  state: number
  last_review?: number
}

export interface SavedPhrase extends SavedBase {
  itemType: 'PHRASE'
  text: string
  translation: string | null
  source: VideoRef
}

export type SavedItem = SavedWord | SavedPhrase

export interface VideoRef {
  source: 'YOUTUBE'
  videoId: string
  title: string
  startMs: number
  endMs: number
}

export type Provider =
  | 'claude'
  | 'openai'
  | 'grok'
  | 'deepseek'
  | 'gemini'
  | 'openrouter'
  | 'ollama'
  | 'lmstudio'
  | 'local'

/** Voice for the play buttons. */
export type Voice = 'browser' | 'openai' | 'gemini' | 'local'

export interface Settings {
  /** Off: LingoMingo shows nothing on YouTube. */
  enabled: boolean
  /** Language of the LingoMingo interface. Empty: the browser language. */
  uiLang: string
  studyLang: string
  nativeLang: string
  provider: Provider
  claudeKey: string
  claudeModel: string
  openaiKey: string
  openaiModel: string
  grokKey: string
  grokModel: string
  deepseekKey: string
  deepseekModel: string
  geminiKey: string
  geminiModel: string
  openrouterKey: string
  openrouterModel: string
  ollamaBaseUrl: string
  ollamaModel: string
  lmstudioBaseUrl: string
  lmstudioModel: string
  /** Other OpenAI-compatible endpoint (llama.cpp server, vLLM, ...). */
  localBaseUrl: string
  localModel: string
  voice: Voice
  openaiVoiceModel: string
  openaiVoice: string
  geminiVoiceModel: string
  geminiVoice: string
  /** OpenAI-compatible speech server, for `voice: 'local'` (Kokoro-FastAPI, Speaches, ...). */
  voiceBaseUrl: string
  voiceModel: string
  voiceName: string
  autoPause: boolean
  /** Show the YouTube subtitle bar at the top of the video, not the bottom. */
  subtitlesOnTop: boolean
  /** Last state of the YouTube player toggles. Videos in the native language start with both off. */
  showSubtitles: boolean
  showSubtitlesList: boolean
  /** Videos in the native language start and save the toggles like other videos. */
  nativeVideosLikeOthers: boolean
  hideTranslation: boolean
  /** Hide the buttons on the subtitle bar. The keyboard shortcuts still work. */
  hideSubtitleButtons: boolean
  /** Font of the subtitle bar and list text. Empty: the default font. */
  subtitleFont: string
  /** Subtitle bar background opacity, in percent. */
  subtitleBgOpacity: number
  /** Subtitle bar text size, in px. The translation line is smaller in the same ratio. */
  subtitleTextSize: number
  /** Subtitle list text size, in px. */
  listTextSize: number
  /** Vocabulary level by study language: words up to this frequency rank count as known. */
  vocabLevels: Record<string, number>
  showKnownGreen: boolean
  showSuggested: boolean
  darkenRare: boolean
  /** Channel IDs shown at the top of the channel list on the Media page. */
  pinnedChannels: string[]
  /** Channels the user added to the Media page channel list, by study language. */
  customChannels: Record<string, { id: string; name: string }[]>
  /** Media page: hide YouTube Shorts from the video list. */
  hideShorts: boolean
}

